package com.minimarket.venta.repository; import com.minimarket.venta.entity.Venta; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface VentaRepository extends JpaRepository<Venta,Long>{Optional<Venta> findByNumeroVenta(String numeroVenta);Page<Venta> findAllByOrderByFechaVentaDesc(Pageable p);}